import React, { useState } from "react";
import { useTranslation } from "gatsby-plugin-react-i18next";
import menuData from "../data/data.json";
import images from "../images";

export default function Navigation() {
  const { t } = useTranslation();
  const [isOpen, setIsOpen] = useState(false);
  const menuItems = menuData.menu ?? [];

  const getMenuLink = (item: string) => {
    if (item === "login") {
      return {
        href: "https://www.buildinglink.com/v2/tenant/home/defaultnew.aspx",
        target: "_blank",
        rel: "noreferrer",
      };
    }
    if (item === "available") {
      return {
        href: "https://streeteasy.com/building/chester-court",
        target: "_blank",
        rel: "noreferrer",
      };
    }
    if (item === "home") {
      return { href: "/" };
    }
    return { href: `/${item}` };
  };

  return (
    <nav className="shadow-md flex flex-row w-full max-w-full">
      <div className="flex flex-row w-full justify-between menu_item_desk">
          <a href="/" className={styles.logoContainer}>
            <img
              src={images.logo.src}
              alt={images.logo.alt}
              width={94}
              height={125}
              className={styles.logo}
              decoding="async"
            />
          </a>
        {/* Desktop Menu */}
        <ul className="hidden sm:flex flex-row gap-6 items-center w-full justify-center">
          <li>
          </li>
          {menuItems.map((item, index) => {
            const link = getMenuLink(item);
            return (
              <li key={index}>
                <a
                  href={link.href}
                  target={link.target}
                  rel={link.rel}
                  className="text-warm_ivory hover:text-beige"
                >
                  {t(`menu.${item}`)}
                </a>
              </li>
            );
          })}
        </ul>

        {/* Mobile Menu Button */}
        <button onClick={() => setIsOpen(!isOpen)} className="md:hidden text-warm_ivory pr-6">
          {isOpen ? (
            <span className="right-4 top-4 absolute z-40 text-warm_ivory">
              <svg
                xmlns="http://www.w3.org/2000/svg"
                width="24"
                height="24"
                viewBox="0 0 24 24"
                fill="none"
                className="bg-terracota"
                aria-hidden="true"
              >
                <path
                  d="M18 6L6 18M6 6L18 18"
                  stroke="currentColor"
                  strokeWidth="2"
                  strokeLinecap="round"
                />
              </svg>
            </span>
          ) : (
            <svg
              xmlns="http://www.w3.org/2000/svg"
              width="24"
              height="24"
              viewBox="0 0 24 24"
              fill="none"
              aria-hidden="true"
            >
              <path
                d="M4 7H20M4 12H20M4 17H20"
                stroke="currentColor"
                strokeWidth="2"
                strokeLinecap="round"
              />
            </svg>
          )}
        </button>
      </div>

      {/* Mobile Menu */}
      {isOpen && (
        <ul className="flex md:hidden flex-col shadow-md menu_item_mob w-full bg-beige min-h-full absolute z-20 top-0 text-center py-8">
          {menuItems.map((item, index) => {
            const link = getMenuLink(item);
            return (
              <li key={index}>
                <a
                  href={link.href}
                  target={link.target}
                  rel={link.rel}
                  onClick={() => setIsOpen(false)}
                  className={`text-terracota hover:text-dark_gray block menu_item_mobile ${
                    index < menuItems.length - 1 ? "py-4" : "pt-4 pb-0"
                  }`}
                >
                  {t(`menu.${item}`)}
                </a>
                {index < menuItems.length - 1 && (
                  <div className={styles.divider}></div>
                )}
              </li>
            );
          })}
        </ul>
      )}
    </nav>
  );
}

const styles = {
  logoContainer: "flex shadow-xl",
  logo: "w-[110px] h-[141px] object-contain p-2 bg-beige/80",
  divider : "w-1/2 h-[1px] bg-dark_gray flex mx-auto"
};
