import React, { useState } from "react";
// import footerData from "../data/data.json";
import { useTranslation } from "gatsby-plugin-react-i18next";

interface FooterData {
  name: string;
  address: string;
  city: string;
  postalCode: string;
  contact: Array<{
    name: string;
    companyName: string;
    address: string;
    city: string;
    zipCode: string;
    mainPhone: string;
    directPhone: string;
    email: string;
  }>;
}

const Footer: React.FC<{ dataFooter: FooterData }> = ( { dataFooter } ) => {
    const footerInfo = dataFooter;
  const footerItems = footerInfo.contact[0];
  const [currentYear, setYear] = useState<number | null>(null);

  React.useEffect(() => {
    setYear(new Date().getFullYear());
  }, []);

  const {t} = useTranslation();

  return (
      <footer className={styles.container}>
        <article className={styles.content}>
          <div className={styles.block}>
            <h3 className={styles.titles}>{t("footer.contactUs")}</h3>
            <p className="body_desk mb-1 text-terracota">{footerItems.name}</p>
            <p className="body_desk mb-1 text-terracota">{footerItems.companyName}</p>
            <p className="body_desk mb-1 text-terracota font-bold">{footerItems.address} {footerItems.city}, {footerItems.zipCode}</p>
            <p className="body_desk text-terracota">{t("footer.main")} {footerItems.mainPhone} | {t("footer.direct")} {footerItems.directPhone}</p>
            <p className="body_desk text-terracota">{t("footer.email")} <a href={`mailto:${footerItems.email}`}>{footerItems.email}</a></p>
          </div>
          <div className={styles.block}>
            <h3 className={styles.titles}>{footerInfo.name}</h3>
            <p className="body_desk mb-1 text-terracota">{footerInfo.address}</p>
            <p className="body_desk text-terracota">{footerInfo.city}, {footerInfo.postalCode}</p>
          </div>
        </article>
        <article className={styles.bottomBar}>
          <p>&copy; {currentYear} {footerInfo.name}. {t("footer.allRights")}</p>
        </article>
      </footer>
  );
};

export default Footer;

const styles = {
    container : "relative bg-beige max-w-full w-full shadow-lg sm:shadow-xl",
    content : "flex flex-col sm:flex-row flex-1 w-full justify-around",
    block: "flex flex-col py-8 px-12 sm:px-0",
    bottomBar: "bg-dark_gray text-center py-4 text-warm_ivory subtext_desk",
    titles: "h2_desk text-dark_gray font-semibold mb-4"
}